SELECT lname FROM authors WHERE authid = (
    SELECT authid FROM authorship GROUP BY authid ORDER BY COUNT(paperid) DESC LIMIT 1
)

SELECT * FROM street_markets WHERE market_id IN (
    SELECT tourist_attraction_id FROM tourist_attractions WHERE how_to_get_there LIKE '%walk%' OR how_to_get_there LIKE '%bus%'
)

SELECT lastname FROM band WHERE id IN (
    SELECT bandmate FROM performance GROUP BY bandmate ORDER BY COUNT(stageposition) DESC LIMIT 1
)
